/* Shared categories are independent of workspace saves and record access. */
(()=>{'use strict';
const api=()=>window.CAGE_BACKEND,me=()=>api()?.currentProfile?.();
const configs=[['requests','request-form','type'],['crm','deal-form','category'],['projects','project-form','category']];
const items=[];
function append(select,names){const known=new Set([...select.options].map(o=>o.value.toLowerCase()));for(const name of names){if(typeof name!=='string'||known.has(name.toLowerCase()))continue;const option=new Option(name,name);option.dataset.sharedCategory="true";select.add(option);known.add(name.toLowerCase());}}
for(const [module,formId,field] of configs){
 const form=document.getElementById(formId),select=form?.elements[field];if(!select)continue;
 const box=document.createElement('div');box.innerHTML='<button type="button" class="secondary-button" data-category-open>+ Add category</button><div data-category-entry hidden><input type="text" maxlength="60" minlength="3" aria-label="New shared category" placeholder="Category name"><button type="button" class="secondary-button" data-category-save>Add</button><button type="button" class="secondary-button" data-category-cancel>Cancel</button></div><small role="status" data-category-message></small>';
 select.after(box);const input=box.querySelector('input'),entry=box.querySelector('[data-category-entry]'),button=box.querySelector('[data-category-save]'),message=box.querySelector('[data-category-message]');let request=0;
 const item={module,select,box,load:async()=>{const uid=me()?.id,token=++request;if(!uid||me()?.role==='shared'){box.hidden=true;return;}box.hidden=false;try{const names=await api().categoryList(module);if(token===request&&uid===me()?.id){append(select,names);message.textContent='';}}catch{if(token===request)message.textContent='Shared categories could not load. Existing choices remain available.';}}};items.push(item);
 box.querySelector('[data-category-open]').addEventListener('click',()=>{entry.hidden=false;input.focus();});box.querySelector('[data-category-cancel]').addEventListener('click',()=>{entry.hidden=true;input.value='';message.textContent='';});
 async function save(){if(button.disabled)return;const name=input.value.trim().replace(/\s+/g,' ');if(name.length<3||name.length>60){message.textContent='Enter a category name of 3 to 60 characters.';return;}const known=[...select.options].find(o=>o.value.toLowerCase()===name.toLowerCase());if(known){select.value=known.value;entry.hidden=true;message.textContent='Existing category selected.';return;}
 const uid=me()?.id;button.disabled=true;try{const saved=await api().categoryAdd(module,name);if(uid!==me()?.id)return;append(select,[saved]);select.value=saved;select.dispatchEvent(new Event('change',{bubbles:true}));input.value='';entry.hidden=true;message.textContent='Category saved for the team.';}catch{message.textContent='Category was not saved. Check your connection and try again.';}finally{button.disabled=false;}}
 button.addEventListener('click',save);input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();e.stopPropagation();save();}});
 const dialog=form.closest('dialog');new MutationObserver(()=>{if(dialog.open){entry.hidden=true;item.load();}}).observe(dialog,{attributes:true,attributeFilter:['open']});
}

// A separate catalogue dialog lets view-only staff add labels without opening an editable record.
const managerButton=document.createElement('button');managerButton.type='button';managerButton.className='secondary-button';managerButton.textContent='Categories';managerButton.hidden=!me()||me().role==='shared';document.querySelector('.topbar-actions')?.append(managerButton);
const manager=document.createElement('dialog');manager.className='app-dialog';manager.setAttribute('aria-label','Shared categories');manager.innerHTML='<form><div class="dialog-heading"><h2>Shared categories</h2><button type="button" class="secondary-button" data-close>Close</button></div><p>Add a category for your team. This does not change who can create or edit records.</p><label class="field"><span>Section</span><select name="module"><option value="requests">New requests</option><option value="crm">CRM opportunities</option><option value="projects">Projects</option></select></label><label class="field"><span>New category</span><input name="category" minlength="3" maxlength="60" required></label><button type="submit" class="primary-button">Add category</button><p role="status"></p><ul></ul></form>';document.body.append(manager);const managerForm=manager.querySelector('form'),managerMessage=manager.querySelector('[role=status]'),managerList=manager.querySelector('ul');let managerVersion=0;
async function showList(){const version=++managerVersion,uid=me()?.id;managerList.replaceChildren();try{const names=await api().categoryList(managerForm.elements.module.value);if(version!==managerVersion||uid!==me()?.id||!manager.open)return;for(const name of names){const li=document.createElement('li');li.textContent=name;managerList.append(li);}}catch{managerMessage.textContent='Could not load shared categories.';}}
managerButton.addEventListener('click',()=>{manager.showModal();managerMessage.textContent='';showList();});manager.querySelector('[data-close]').addEventListener('click',()=>manager.close());manager.addEventListener('close',()=>{managerVersion++;managerList.replaceChildren();});managerForm.elements.module.addEventListener('change',showList);
managerForm.addEventListener('submit',async e=>{e.preventDefault();const b=managerForm.querySelector('[type=submit]');if(b.disabled)return;const uid=me()?.id,module=managerForm.elements.module.value,name=managerForm.elements.category.value.trim().replace(/\s+/g,' ');b.disabled=true;try{const item=items.find(i=>i.module===module),existing=[...item.select.options].find(o=>o.value.toLowerCase()===name.toLowerCase());const saved=existing?.value||await api().categoryAdd(module,name);if(uid!==me()?.id)return;append(item.select,[saved]);managerMessage.textContent=existing?'That category already exists.':'Category saved for the team.';managerForm.elements.category.value='';showList();}catch{managerMessage.textContent='Category was not saved. Use 3–60 characters and check your connection.';}finally{b.disabled=false;}});

window.CAGE_CATEGORIES={select:(formId,name)=>{const select=document.getElementById(formId)?.elements.category;if(select){append(select,name?[name]:[]);select.value=name||'';}}};
window.addEventListener('cage:session-ready',()=>{for(const i of items){for(const o of i.select.querySelectorAll('[data-shared-category]'))o.remove();i.load();}manager.close();managerForm.reset();managerMessage.textContent='';managerList.replaceChildren();managerButton.hidden=!me()||me().role==='shared';});
for(const i of items)if(me())i.load();
})();
